def recovery_request(original):
 if len(original)!=4194304:raise ValueError('Unexpected misc size')
 prefix=bytearray(864);prefix[:14]=b'boot-recovery\0';prefix[64:74]=b'recovery\n\0'
 if original[:864] not in (bytes(864),bytes(prefix)):raise ValueError('Pending foreign bootloader request; refusing replacement')
 return bytes(prefix)+original[864:]

def recovery_watch_spec(label,port,run_id,evidence=None):
 match=re.fullmatch(r'native-ios-r([0-9]+)',label)
 if not match or port not in (5037,5038,5047,15049) or not re.fullmatch('[0-9a-f]{32}',run_id):
  raise ValueError('Invalid recovery watcher identity')
 if not Path(__file__).with_name('watch-native-recovery.py').is_file():raise FileNotFoundError('Recovery watcher script missing')
 evidence=N/'evidence' if evidence is None else Path(evidence)
 capture=evidence/('logfs-recovery-r'+match[1])
 console=capture.with_name(capture.name+'-watch.stdout.log')
 pid=capture.with_name(capture.name+'-watch.pid.json')
 status=capture.with_name(capture.name+'-watch.json')
 if any(path.exists() for path in (capture,console,pid,status)):
  raise FileExistsError('Recovery watcher/capture already exists; preserve it before another boot')
 return {'command':[sys.executable,str(Path(__file__).with_name('watch-native-recovery.py')),
  '--run',match[1],'--run-id',run_id,'--output',str(capture),'--first-port',str(port),'--timeout','600'],
  'capture':capture,'console':console,'pid':pid,'status':status}

def start_recovery_watch(spec):
 # Separate process/session and redirected handles keep monitoring alive when
 # the boot command returns to the caller. No sleep or fixed grace period.
 if any(spec[key].exists() for key in ('capture','console','pid','status')):
  raise FileExistsError('Recovery watcher destination already occupied')
 spec['console'].parent.mkdir(parents=True,exist_ok=True)
 with spec['pid'].open('x') as pidfile,spec['console'].open('xb') as console:
  child=subprocess.Popen(spec['command'],stdin=subprocess.DEVNULL,stdout=console,
   stderr=subprocess.STDOUT,start_new_session=True,close_fds=True)
  json.dump({'pid':child.pid,'command':spec['command'],'capture':str(spec['capture']),
   'started_at':datetime.datetime.now().astimezone().isoformat(),'fixed_grace_sleep':False},pidfile,indent=2)
  pidfile.write('\n')
 return child.pid

